// Planificador de trayectoria articular libre de colisiones (Inicio -> Paso Intermedio -> Final)
const modoOptimizacion = (entrada && entrada.modoOptimizacion) ? entrada.modoOptimizacion : "multiobjetivo";
const iniX = Number(entrada?.inicioX !== undefined ? entrada.inicioX : 55);
const iniY = Number(entrada?.inicioY !== undefined ? entrada.inicioY : -35);
const objX = Number(entrada?.objetivoX !== undefined ? entrada.objetivoX : 55);
const objY = Number(entrada?.objetivoY !== undefined ? entrada.objetivoY : 40);
const obsX = Number(entrada?.obstaculoX !== undefined ? entrada.obstaculoX : 35);
const obsY = Number(entrada?.obstaculoY !== undefined ? entrada.obstaculoY : 5);
const obsR = Number(entrada?.obstaculoRadio !== undefined ? entrada.obstaculoRadio : 16);
const inicio = { x: iniX, y: iniY };
const objetivo = { x: objX, y: objY };
const obstaculo = { x: obsX, y: obsY, radio: obsR };
const [L1, L2, L3] = [45, 35, 25];

const distSegmento = (p, a, b) => {
  const abx = b.x - a.x, aby = b.y - a.y;
  const l2 = abx * abx + aby * aby;
  if (l2 === 0) return Math.hypot(p.x - a.x, p.y - a.y);
  const t = Math.max(0, Math.min(1, ((p.x - a.x) * abx + (p.y - a.y) * aby) / l2));
  return Math.hypot(p.x - (a.x + t * abx), p.y - (a.y + t * aby));
};

const q0 = [vars.ini1, vars.ini2, vars.ini3];
const q1 = [vars.via1, vars.via2, vars.via3];
const q2 = [vars.fin1, vars.fin2, vars.fin3];
const muestras = 24;
const radioSeguro = obstaculo.radio + 1.5;

let minDist = Infinity, penCol = 0, lenPath = 0, prevP3 = null;
let p3Ini = null, p3Fin = null;

for (let k = 0; k <= muestras; k++) {
  const s = k / muestras;
  const u = s <= 0.5 ? s * 2.0 : (s - 0.5) * 2.0;
  const a = s <= 0.5 ? q0 : q1;
  const b = s <= 0.5 ? q1 : q2;
  const th1 = a[0] + (b[0] - a[0]) * u;
  const th2 = a[1] + (b[1] - a[1]) * u;
  const th3 = a[2] + (b[2] - a[2]) * u;
  const a1 = (th1 * Math.PI) / 180;
  const a2 = a1 + (th2 * Math.PI) / 180;
  const a3 = a2 + (th3 * Math.PI) / 180;
  const p0 = { x: 0, y: 0 };
  const p1 = { x: L1 * Math.cos(a1), y: L1 * Math.sin(a1) };
  const p2 = { x: p1.x + L2 * Math.cos(a2), y: p1.y + L2 * Math.sin(a2) };
  const p3 = { x: p2.x + L3 * Math.cos(a3), y: p2.y + L3 * Math.sin(a3) };
  if (k === 0) p3Ini = p3;
  if (k === muestras) p3Fin = p3;
  if (prevP3) lenPath += Math.hypot(p3.x - prevP3.x, p3.y - prevP3.y);
  prevP3 = p3;
  const d = Math.min(
    distSegmento(obstaculo, p0, p1),
    distSegmento(obstaculo, p1, p2),
    distSegmento(obstaculo, p2, p3)
  );
  if (d < minDist) minDist = d;
  if (d < radioSeguro) penCol += (radioSeguro - d);
}

const errIni = Math.hypot(p3Ini.x - inicio.x, p3Ini.y - inicio.y);
const errFin = Math.hypot(p3Fin.x - objetivo.x, p3Fin.y - objetivo.y);
const errTotal = errIni + errFin;
const rotTotal = Math.abs(q1[0] - q0[0]) + Math.abs(q1[1] - q0[1]) + Math.abs(q1[2] - q0[2])
               + Math.abs(q2[0] - q1[0]) + Math.abs(q2[1] - q1[1]) + Math.abs(q2[2] - q1[2]);

const violacion = penCol * 6.0
  + (minDist < radioSeguro ? (radioSeguro - minDist) * 18.0 : 0.0)
  + Math.max(0.0, errIni - 5.0) * 6.0
  + Math.max(0.0, errFin - 5.0) * 6.0;

const objRecorrido = lenPath * 0.1 + rotTotal * 0.015 + Math.max(0.0, errTotal - 2.0) * 3.0;
if (modoOptimizacion === "monobjetivo") {
  return { fitness: errTotal * 2.5 + objRecorrido * 0.25, violacion };
}
return { fitness: [errTotal, objRecorrido], violacion };
